import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/lib/cn'

// shadcn's empty in the brand: what shows where a list has nothing in it yet. A dashed #666666 hairline with the brand
// corner on Black, a 20px Lucide icon in a #262626 tile, a Funnel Display title, one muted line on what is missing and
// the actions that fill it. No illustrations, and never without a way forward.
export interface EmptyProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** What is missing, in Funnel Display. */
  title: string
  /** One muted line on how to fill it. */
  description?: string
  /** A 20px Lucide icon. */
  icon?: ReactNode
}

export function Empty({ title, description, icon, className, children, ...rest }: EmptyProps) {
  return (
    <div data-ds="empty" className={cn('flex w-full flex-col items-center gap-2 rounded-container border border-dashed border-edge-strong px-6 py-12 text-center', className)} {...rest}>
      {icon && <span className="mb-2 flex size-10 items-center justify-center rounded-control bg-surface-raised text-fg" aria-hidden="true">{icon}</span>}
      <p className="type-heading-4 text-fg">{title}</p>
      {description && <p className="max-w-sm type-ui text-fg-muted">{description}</p>}
      {children && <div className="mt-4 flex flex-wrap justify-center gap-3">{children}</div>}
    </div>
  )
}

export default Empty

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
